// Turn each email into the ticket shape the triage webhook expects. Only the
// subject, text and date are used; the sender's address is not passed on.
const stripHtml = (html) =>
  String(html == null ? '' : html)
    .replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/(p|div|li|tr|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

const out = [];
for (const item of $input.all()) {
  const mail = (item && item.json) || {};
  const metadata = mail.metadata && typeof mail.metadata === 'object' ? mail.metadata : {};
  const header = (name) => {
    const value = mail[name] != null ? mail[name] : metadata[name];
    return typeof value === 'string' ? value : '';
  };
  const subject = header('subject');
  const plain = typeof mail.textPlain === 'string' ? mail.textPlain.trim() : '';
  const body = plain || stripHtml(mail.textHtml);

  const parsed = Date.parse(header('date'));
  const receivedAt = new Date(Number.isNaN(parsed) ? Date.now() : parsed).toISOString();

  // Stable id from the Message-ID header, so a re-read email keeps its id.
  const seed = header('message-id') || header('messageId') || subject + '|' + receivedAt;
  let hash = 5381;
  for (let i = 0; i < seed.length; i++) hash = ((hash * 33) ^ seed.charCodeAt(i)) >>> 0;
  const id = 'E-' + receivedAt.replace(/\D/g, '').slice(0, 14) + '-' + hash.toString(36);

  out.push({ json: { ticket: { id, received_at: receivedAt, channel: 'email', subject, body } } });
}
return out;
